// === TRACCIABILITA (lotti padre di un semilavorato) ===
function Tracciabilita({lot}){const[par,setPar]=useState(null);const[ddtAbc,setDdtAbc]=useState(null);useEffect(()=>{let on=true;(async()=>{try{const{data:bridge}=await supabase.from("trasformazione_input").select("padre_id,qta").eq("figlio_id",lot.id);const ids=[...new Set([...(bridge||[]).map(b=>b.padre_id),...(lot.lotto_padre?[lot.lotto_padre]:[])])];if(ids.length===0){if(on){setPar([]);setDdtAbc(null)}return}const{data:padri}=await supabase.from("lotti").select("*").in("id",ids);const{data:trm}=await supabase.from("movimenti").select("lotto_id,ddt,data").eq("tipo","TRASFERIMENTO").eq("magazzino","ABC Service").in("lotto_id",ids);const dMap={};(trm||[]).forEach(m=>{if(m.ddt&&String(m.ddt).trim()){if(!dMap[m.lotto_id]||String(m.data)>String(dMap[m.lotto_id].data))dMap[m.lotto_id]={ddt:m.ddt,data:m.data}}});const qById={};(bridge||[]).forEach(b=>{qById[b.padre_id]=b.qta});const out=(padri||[]).map(p=>({...p,qScar:qById[p.id],ddtAnd:dMap[p.id]?dMap[p.id].ddt:null}));if(on){setPar(out);setDdtAbc([...new Set(out.map(p=>p.ddtAnd).filter(Boolean))])}}catch(e){if(on)setPar([])}})();return()=>{on=false}},[lot.id]);if(par===null)return <div style={{fontSize:12,color:C.tM}}>Carico tracciabilita...</div>;if(par.length===0)return <div style={{fontSize:12,color:C.tM}}>Lotto di origine: non deriva da trasformazione o trasferimento.</div>;return <div style={{display:"flex",flexDirection:"column",gap:6}}><div style={{fontSize:11,fontWeight:800,color:C.acc,textTransform:"uppercase",letterSpacing:.8,display:"flex",gap:12,alignItems:"center",flexWrap:"wrap"}}>Lotti padre ({par.length}){ddtAbc&&ddtAbc.length>0&&<span style={{fontWeight:700,color:C.b,background:C.bD,borderRadius:5,padding:"2px 8px",letterSpacing:.3,textTransform:"none"}}>DDT andata ABC: {ddtAbc.join(", ")}</span>}</div>{par.map(p=><div key={p.id} style={{display:"flex",gap:12,flexWrap:"wrap",alignItems:"center",padding:"6px 10px",background:C.zebra,borderRadius:6,fontSize:12}}><span style={{fontWeight:700,color:C.t}}>{p.lotto} - {p.imballo}</span><span style={{color:C.tM}}>{p.desc1} · {p.desc2} · {p.desc3}</span>{p.qScar!=null&&<span style={{fontFamily:"'DM Mono',monospace",color:C.acc}}>scaricati {Number(p.qScar).toLocaleString("it-IT")} kg</span>}<span style={{color:C.tM}}>racc. {p.anno_raccolta||"-"} · mag. {p.magazzino}</span>{p.ddtAnd&&<span style={{fontFamily:"'DM Mono',monospace",color:C.b,fontWeight:700}}>DDT and. {p.ddtAnd}</span>}<span style={{marginLeft:"auto",fontFamily:"'DM Mono',monospace",fontSize:11}}>M.O. <b style={{color:moP(p)>4?C.r:moP(p)>2?C.o:C.g}}>{pct(p.mo)}</b> · C.O. <b style={{color:coP(p)>4?C.r:coP(p)>2?C.o:C.g}}>{pct(p.co)}</b> · M.V. {pct(p.mv)} · C.V. {pct(p.cv)} · C.E. {pct(p.ce)} · RT {pct(p.rt)}</span></div>)}</div>;}

// === ETICHETTE QR (stampa DYMO, una etichetta per pagina) ===
async function stampaEtichette(lots){if(!lots||lots.length===0)return;const doc=new jsPDF({orientation:"landscape",unit:"mm",format:[LABEL.w,LABEL.h]});for(let i=0;i<lots.length;i++){const l=lots[i];if(i>0)doc.addPage([LABEL.w,LABEL.h],"landscape");let qrData="";try{qrData=await QRCode.toDataURL(QR_PREFIX+l.id,{margin:0,width:260})}catch(_){}const qs=Math.min(LABEL.h-8,46);if(qrData)doc.addImage(qrData,"PNG",4,(LABEL.h-qs)/2,qs,qs);const x=qs+9;doc.setTextColor(15,15,15);doc.setFont("helvetica","bold");doc.setFontSize(16);doc.text(String(l.lotto||""),x,15);doc.setFont("helvetica","normal");doc.setFontSize(12);doc.setTextColor(55,55,55);doc.text(String(l.imballo||""),x,24);doc.setFontSize(10);doc.text(String(l.desc1||""),x,34);doc.setFont("helvetica","bold");doc.setFontSize(14);doc.setTextColor(15,15,15);doc.text("Cal. "+String(l.desc3||""),x,44);}doc.save("etichette_"+new Date().toISOString().split("T")[0]+".pdf")}
function parseQR(txt){if(!txt)return null;const s=String(txt).trim();if(!s.startsWith(QR_PREFIX))return null;const id=s.slice(QR_PREFIX.length).trim();return id||null}

// === SCANNER QR (fotocamera, html5-qrcode) ===
function Scanner({onScan,onClose,title}){const[err,setErr]=useState("");const done=useRef(false);useEffect(()=>{let scanner;let cancelled=false;(async()=>{let H;try{const mod=await import("html5-qrcode");H=mod.Html5Qrcode}catch(e){if(!cancelled)setErr("Caricamento scanner fallito");return}if(cancelled)return;try{scanner=new H("qr-reader-box")}catch(e){setErr("Init fotocamera fallita");return}scanner.start({facingMode:"environment"},{fps:10,qrbox:{width:230,height:230}},(txt)=>{if(done.current)return;done.current=true;scanner.stop().then(()=>onScan(txt)).catch(()=>onScan(txt))},()=>{}).catch(e=>setErr("Fotocamera non disponibile. Consenti l'accesso o usa HTTPS. ("+(e&&e.message?e.message:e)+")"))})();return()=>{cancelled=true;try{scanner&&scanner.stop().catch(()=>{})}catch(_){}}},[]);return <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.88)",zIndex:120,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:16}}><div style={{color:"#fff",marginBottom:14,fontWeight:700,fontSize:16,textAlign:"center"}}>{title||"Inquadra il QR del big bag"}</div><div id="qr-reader-box" style={{width:"100%",maxWidth:340,borderRadius:14,overflow:"hidden",background:"#000"}}/>{err&&<div style={{color:"#ffd479",marginTop:14,fontSize:13,textAlign:"center",maxWidth:340}}>{err}</div>}<button onClick={onClose} style={{marginTop:20,padding:"11px 28px",borderRadius:10,border:"1px solid #ffffff55",background:"transparent",color:"#fff",cursor:"pointer",fontSize:15,fontWeight:600}}>Chiudi</button></div>}

