      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(150px,1fr))",gap:12,marginBottom:18}}><Inp label="Data" type="date" value={form.data} onChange={v=>setForm({...form,data:v})}/><Inp label="Annata raccolta" value={form.anno_raccolta} onChange={v=>setForm({...form,anno_raccolta:v})} placeholder="2025"/><Inp label="Anno lavoraz." value={form.anno} onChange={v=>setForm({...form,anno:v})}/><Inp label="Sett. lavoraz." value={form.sett} onChange={v=>setForm({...form,sett:v})}/><Inp label="Imballo *" value={form.imballo} onChange={v=>setForm({...form,imballo:v})} placeholder="BIG BAG N..."/><Inp label="Lotto *" value={form.lotto} onChange={v=>setForm({...form,lotto:v})} placeholder="SO112024"/></div>
